var p=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerController>();var e=p.visual.GetComponent<Bulldozer.Player.MinerEquipment>();var rock=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None).Where(r=>r.naturalBoulder).OrderBy(r=>r.blockId).First();var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=rock.transform.position-Vector3.forward*1.05f+Vector3.up*.03f;cc.enabled=true;p.visual.rotation=Quaternion.identity;p.autoMine=true;p.touchControls.Move=Vector2.zero;Physics.SyncTransforms();float began=Time.realtimeSinceStartup;Time.captureDeltaTime=1f/30;EditorApplication.isPaused=false;EditorApplication.CallbackFunction tick=null;tick=()=>{if(!EditorApplication.isPlaying){EditorApplication.update-=tick;return;}if(rock.Depleted||Time.realtimeSinceStartup-began>20){bool pass=rock.Depleted&&e.IsBlockDepleted(rock.blockId)&&e.Snapshot.taskRocks==1;System.IO.File.AppendAllText("Maintenance/Miner/full-loop-restart-verification.txt","\n"+(pass?"PASS ":"FAIL ")+"Round two natural rock breaks through actual pickaxe animation and saves new progress");p.autoMine=false;p.CancelMining();EditorApplication.update-=tick;Time.captureDeltaTime=0;EditorApplication.isPaused=true;}};EditorApplication.update+=tick;return "Checking actual mining resumes in round two";
